using Microsoft.EntityFrameworkCore;
namespace Decont;
public static class Finance {
 public static void Map(RouteGroupBuilder api){var f=api.MapGroup("/finance").RequireAuthorization(p=>p.RequireRole("Finance"));
 f.MapGet("/vendors",async(Db db)=>await db.Vendors.ToListAsync());
 f.MapPost("/vendors/{id:guid}/resolve",async(Guid id,VendorInput i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Reason(i.Reason);Guard.Require(!string.IsNullOrWhiteSpace(i.Account),"account","Completează contul ERP.","ERP account required.");var v=await db.Vendors.FindAsync(id)??throw new DomainException("missing","Solicitare inexistentă.","Request not found.",404);Guard.Require(v.State=="Pending","state","Solicitarea a fost rezolvată.","Request already resolved.");var masters=await db.Masters.Where(m=>m.Kind=="suppliers"&&m.Code==v.Cui).ToListAsync();Guard.Require(!masters.Any(m=>m.Active&&(m.To==null||m.To>=i.From)),"overlap","Închide versiunea anterioară a furnizorului.","Close the previous supplier version first.");db.Masters.Add(new(){Kind="suppliers",Code=v.Cui,NameRo=v.Supplier,NameEn=v.Supplier,From=i.From,Json=Serialization.Write(new{vendorAccount=i.Account})});v.State="Resolved";v.Account=i.Account;svc.Log(c.User,v.ReportId,id.ToString(),"VendorResolved",after:new{i.Account,i.From},reason:i.Reason);return v;}));
 f.MapGet("/transactions",async(Db db)=>new{transactions=await db.Transactions.ToListAsync(),matches=await db.Matches.ToListAsync()});
 f.MapPost("/transactions/preview",async(BankInput i,Db db)=>{await Card(db,i.CardId);var rows=Parse(i);var existing=await db.Transactions.Where(t=>t.CardId==i.CardId).Select(t=>t.Reference).ToListAsync();return new{rows,duplicates=rows.Where(t=>existing.Contains(t.Reference)).Select(t=>t.Reference),count=rows.Count};});
 f.MapPost("/transactions/import",async(BankInput i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{await Card(db,i.CardId);var rows=Parse(i);Guard.Require(rows.Select(r=>r.Reference).Distinct().Count()==rows.Count,"duplicate","Referințe duplicate în fișier.","Duplicate references in file.");var existing=await db.Transactions.Where(t=>t.CardId==i.CardId).Select(t=>t.Reference).ToListAsync();Guard.Require(!rows.Any(t=>existing.Contains(t.Reference)),"duplicate","Importul include tranzacții existente.","Import contains existing transactions.");db.Transactions.AddRange(rows);svc.Log(c.User,null,i.CardId.ToString(),"StatementImported",after:new{count=rows.Count,hash=Serialization.Hash(i.Csv)});return new{count=rows.Count};}));
 f.MapGet("/suggestions",async(Db db)=>{var masters=await db.Masters.ToListAsync();var lines=await db.Lines.Where(l=>!l.Archived).ToListAsync();var tx=await db.Transactions.ToListAsync();var matches=await db.Matches.ToListAsync();return tx.Select(t=>new{transaction=t,remaining=t.Amount-matches.Where(m=>m.TransactionId==t.Id).Sum(m=>m.Amount),candidates=lines.Where(l=>{var d=l.Data();return d.CardId==t.CardId&&d.Currency==t.Currency&&Math.Abs((DateOnly.Parse(d.Date).ToDateTime(TimeOnly.MinValue)-DateOnly.Parse(t.Date).ToDateTime(TimeOnly.MinValue)).TotalDays)<=7;}).Select(l=>new{l.Id,l.ReportId,amount=l.Data().Amount,score=(l.Data().Amount==t.Amount?60:0)+(l.Data().Date==t.Date?20:0)+(t.Merchant.Contains(l.Data().Supplier,StringComparison.OrdinalIgnoreCase)?20:0),employeeId=masters.Where(m=>m.Kind=="cards"&&m.Id==t.CardId).Select(m=>Rules.Text(m,"ownerId")).FirstOrDefault()}).OrderByDescending(x=>x.score).Take(5)});});
 f.MapPost("/matches",async(MatchInput i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{var r=await svc.Version(i.ReportId,i.Version,c.User);Guard.Require(States.FinanceEdit(r.State),"state","Decontul nu poate fi reconciliat în această stare.","Cannot reconcile this report state.");var l=r.Lines.Single(l=>l.Id==i.LineId&&!l.Archived);var d=l.Data();var t=await db.Transactions.FindAsync(i.TransactionId)??throw new DomainException("missing","Tranzacție inexistentă.","Transaction not found.",404);Guard.Require(d.Payment=="CompanyCard"&&d.CardId==t.CardId&&d.Currency==t.Currency&&i.Amount>0,"match","Asociere invalidă.","Invalid card match.");var tm=await db.Matches.Where(m=>m.TransactionId==t.Id).ToListAsync();var lm=await db.Matches.Where(m=>m.LineId==l.Id).ToListAsync();Guard.Require(tm.Sum(m=>m.Amount)+i.Amount<=t.Amount&&lm.Sum(m=>m.Amount)+i.Amount<=d.Amount,"allocation","Suma depășește disponibilul.","Allocation exceeds the remaining amount.");var allocated=tm.Sum(m=>m.Amount)+i.Amount;var ron=allocated==t.Amount? t.SettledRon-tm.Sum(m=>m.Ron):Rules.Money(t.SettledRon*i.Amount/t.Amount);var m=new Match{LineId=l.Id,TransactionId=t.Id,Amount=i.Amount,Ron=ron,Actor=Reports.Actor(c.User)};db.Matches.Add(m);l.Reconciled=lm.Sum(x=>x.Amount)+i.Amount==d.Amount;l.SettledRon=l.Reconciled?lm.Sum(x=>x.Ron)+ron:null;l.OverrideReason=null;Reports.Touch(r);svc.Log(c.User,r.Id,l.Id.ToString(),"CardMatched",after:m);await svc.Reapproval(r,c.User);return Api.View(r);}));
 f.MapPost("/matches/{id:guid}/undo",async(Guid id,VersionRequest i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Reason(i.Reason);var m=await db.Matches.FindAsync(id)??throw new DomainException("missing","Asociere inexistentă.","Match not found.",404);var line=await db.Lines.FindAsync(m.LineId);var r=await svc.Version(line!.ReportId,i.Version,c.User);Guard.Require(States.FinanceEdit(r.State),"state","Decontul nu poate fi modificat.","Cannot change this report.");var l=r.Lines.Single(l=>l.Id==m.LineId);db.Matches.Remove(m);l.Reconciled=false;l.SettledRon=null;Reports.Touch(r);svc.Log(c.User,r.Id,l.Id.ToString(),"CardMatchUndone",before:m,reason:i.Reason);await svc.Reapproval(r,c.User);return Api.View(r);}));
 f.MapPost("/reports/{id:guid}/lines/{line:guid}/disposition",async(Guid id,Guid line,Disposition i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Reason(i.Reason);var r=await svc.Version(id,i.Version,c.User);Guard.Require(States.FinanceEdit(r.State),"state","Decontul nu poate fi modificat.","Cannot change this report.");var l=r.Lines.Single(l=>l.Id==line&&!l.Archived);if(i.Kind=="cardOverride"){Guard.Require(l.Data().Payment=="CompanyCard","card","Cheltuiala nu este plătită cu cardul.","Expense is not a company card payment.");l.OverrideReason=i.Reason;}else if(i.Kind=="vatOverride"){l.VatOverrideReason=i.Reason;}else if(i.Kind=="notDuplicate"||i.Kind=="duplicateAllowed")l.DuplicateDisposition=i.Reason;else if(i.Kind=="duplicate"){Guard.Require(!await db.Matches.AnyAsync(m=>m.LineId==l.Id),"matched","Anulează alocările înainte de arhivare.","Undo allocations before archival.");l.Archived=true;}else throw new DomainException("kind","Decizie invalidă.","Invalid disposition.");Reports.Touch(r);svc.Log(c.User,id,line.ToString(),i.Kind,after:i.Reason,reason:i.Reason);return Api.View(r);}));
 f.MapPost("/reports/{id:guid}/legal-hold",async(Guid id,HoldInput i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Reason(i.Reason);var r=await svc.Version(id,i.Version,c.User);var before=r.LegalHold;r.LegalHold=i.Hold;Reports.Touch(r);svc.Log(c.User,id,"Retention","LegalHoldChanged",before,i.Hold,i.Reason);return Api.View(r);}));
 f.MapGet("/batches",async(Db db)=>await db.Batches.Select(b=>new{b.Id,b.ReportId,b.Revision,b.Cycle,b.RuleVersion,b.Hash,b.FileHash,b.State,b.Reference,b.At,b.PostedAt}).ToListAsync());
 f.MapPost("/reports/{id:guid}/export",async(Guid id,VersionRequest i,Db db,Reports svc,Posting posting,IStore store,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{var r=await svc.Version(id,i.Version,c.User);Guard.Require(r.State==States.Ready,"state","Finalizează verificarea Finance.","Complete the finance review first.");Guard.Require(!await db.Batches.AnyAsync(b=>b.ReportId==id&&b.State!="Voided"&&b.State!="Reversed"),"export","Există deja un export activ.","An active export already exists.");var issues=await svc.Validate(r,true);Guard.Require(!issues.Any(p=>p.Blocking),"preflight",Serialization.Write(issues),Serialization.Write(issues));var user=await db.Users.FindAsync(r.EmployeeId);var masters=await db.Masters.ToListAsync();var result=posting.Build(r,user!,masters);var rows=Serialization.Write(result.Rows);var b=new Batch{ReportId=id,Revision=r.Revision,Cycle=await db.Batches.CountAsync(b=>b.ReportId==id)+1,RuleVersion=result.Version,Rows=rows,Hash=Serialization.Hash(rows),Actor=Reports.Actor(c.User)};var file=Documents.Workbook(result.Rows);b.Key="batches/"+b.Id+".xlsx";b.FileHash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(file));await store.Put(b.Key,file,"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");db.Batches.Add(b);r.State=States.Exported;Reports.Touch(r);svc.Log(c.User,id,b.Id.ToString(),"ERPExported",after:new{b.Hash,b.Cycle,b.RuleVersion});return new{batchId=b.Id,report=Api.View(r)};}));
 f.MapPost("/batches/{id:guid}/posted",async(Guid id,PostingInput i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Require(!string.IsNullOrWhiteSpace(i.Reference),"reference","Referința ERP este obligatorie.","ERP posting reference required.");var b=await db.Batches.FindAsync(id)??throw new DomainException("missing","Export inexistent.","Batch not found.",404);var r=await svc.Version(b.ReportId,i.Version,c.User);Guard.Require(b.State=="Exported"&&r.State==States.Exported,"state","Exportul nu poate fi postat.","Batch cannot be posted.");b.State="Posted";b.Reference=i.Reference;b.PostedAt=DateTime.UtcNow;r.State=States.Posted;r.RetainUntil=DateTime.UtcNow.AddYears(5);Reports.Touch(r);svc.Log(c.User,r.Id,b.Id.ToString(),"ERPPosted",after:new{i.Reference,b.Hash});await svc.Notify(r,r.EmployeeId,"Posted");return Api.View(r);}));
 f.MapPost("/batches/{id:guid}/reopen",async(Guid id,ReopenInput i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Require(c.User.IsInRole("FinanceReopen"),"permission","Este necesar dreptul FinanceReopen.","FinanceReopen permission required.",403);Guard.Reason(i.Reason);Guard.Require(i.ReversalReference.Trim().Length>=3,"reversal","Completează referința reversării efectuate în ERP.","Provide the reference of the reversal performed in ERP.");var b=await db.Batches.FindAsync(id)??throw new DomainException("missing","Export inexistent.","Batch not found.",404);var r=await svc.Version(b.ReportId,i.Version,c.User);Guard.Require(b.State=="Posted"&&r.State is States.Posted or States.Closed,"state","Se poate redeschide numai un export postat.","Only a posted export can be reopened.");b.State="Reversed";svc.Snapshot(r,c.User);r.State=States.Reapproval;Reports.Touch(r);svc.Log(c.User,r.Id,id.ToString(),"PostedBatchReopened",after:new{i.ReversalReference,b.Hash},reason:i.Reason);await svc.Notify(r,r.ManagerId,"ReapprovalRequired");return Api.View(r);}));
 f.MapPost("/batches/{id:guid}/void",async(Guid id,VersionRequest i,Db db,Reports svc,HttpContext c)=>await Api.Atomic(db,c,i,async()=>{Guard.Require(c.User.IsInRole("FinanceReopen"),"permission","Este necesar dreptul FinanceReopen.","FinanceReopen permission required.",403);Guard.Reason(i.Reason);var b=await db.Batches.FindAsync(id)??throw new DomainException("missing","Export inexistent.","Batch not found.",404);Guard.Require(b.State=="Exported","posted","Exporturile postate necesită reversare ERP externă.","Posted batches require an external ERP reversal.");var r=await svc.Version(b.ReportId,i.Version,c.User);b.State="Voided";r.State=States.Finance;Reports.Touch(r);svc.Log(c.User,r.Id,b.Id.ToString(),"BatchVoided",after:b.Hash,reason:i.Reason);return Api.View(r);}));
 }
 static async Task Card(Db db,Guid id)=>Guard.Require(await db.Masters.AnyAsync(m=>m.Id==id&&m.Kind=="cards"&&m.Active),"card","Card invalid.","Invalid card.");
 public static List<CardTransaction> Parse(BankInput i){Guard.Require(i.Csv.Length<=5*1024*1024,"size","Fișier prea mare.","File too large.");var parsed=Csv.Read(i.Csv);Guard.Require(parsed.Count>1,"csv","CSV gol.","CSV is empty.");var headers=parsed[0];string Get(string[] row,string name){var index=Array.IndexOf(headers,i.Columns.GetValueOrDefault(name)??name);Guard.Require(index>=0&&index<row.Length,"column","Coloană lipsă: "+name,"Column missing: "+name);return row[index];}List<CardTransaction> rows=[];foreach(var row in parsed.Skip(1)){Guard.Require(DateOnly.TryParseExact(Get(row,"date"),"yyyy-MM-dd",out var date),"date","Folosește data ISO YYYY-MM-DD.","Use ISO dates YYYY-MM-DD.");var validAmount=decimal.TryParse(Get(row,"amount"),System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out var amount);var validRon=decimal.TryParse(Get(row,"settledRon"),System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out var ron);Guard.Require(validAmount&&validRon&&amount>0&&ron>0,"amount","Sumele trebuie să fie pozitive.","Amounts must be positive.");rows.Add(new(){CardId=i.CardId,Reference=Get(row,"reference"),Date=date.ToString("yyyy-MM-dd"),Merchant=Get(row,"merchant"),Amount=Rules.Money(amount),Currency=Get(row,"currency").ToUpperInvariant(),SettledRon=Rules.Money(ron)});}return rows;}
}
public record VendorInput(string Account,DateOnly From,string Reason);public record BankInput(Guid CardId,string Csv,Dictionary<string,string> Columns);public record MatchInput(Guid ReportId,long Version,Guid LineId,Guid TransactionId,decimal Amount);public record Disposition(long Version,string Kind,string Reason);public record HoldInput(long Version,bool Hold,string Reason);public record PostingInput(long Version,string Reference);
public static class Csv {
 public static List<string[]> Read(string source,char delimiter=','){List<string[]> rows=[];List<string> row=[];var field=new System.Text.StringBuilder();var quoted=false;for(int j=0;j<source.Length;j++){var c=source[j];if(c=='"'){if(quoted&&j+1<source.Length&&source[j+1]=='"'){field.Append('"');j++;}else quoted=!quoted;}else if(c==delimiter&&!quoted){row.Add(field.ToString());field.Clear();}else if(c=='\n'&&!quoted){row.Add(field.ToString().TrimEnd('\r'));field.Clear();if(row.Any(x=>x!=""))rows.Add(row.ToArray());row.Clear();}else field.Append(c);}Guard.Require(!quoted,"csv","Ghilimele CSV neînchise.","Unclosed CSV quote.");if(field.Length>0||row.Count>0){row.Add(field.ToString().TrimEnd('\r'));rows.Add(row.ToArray());}return rows;}
 public static string Cell(object? x){var s=Convert.ToString(x,System.Globalization.CultureInfo.InvariantCulture)??"";if(s.StartsWith('=')||s.StartsWith('+')||s.StartsWith('-')||s.StartsWith('@'))s="'"+s;return "\""+s.Replace("\"","\"\"")+"\"";}
}

public record ReopenInput(long Version,string Reason,string ReversalReference);
